{
  "findings": [
    {
      "check_id": "CKV_AWS_274",
      "title": "AWS-managed broad S3 policy attached to IAM role",
      "resource": "aws_iam_role.pass1",
      "severity": "MEDIUM",
      "explanation": "The AmazonS3ReadOnlyAccess managed policy grants read and list access across all S3 resources rather than limiting access to specific required buckets. This violates least privilege and increases the impact if the role is assumed by an unintended principal."
    }
  ],
  "patched_code": "resource \"aws_iam_role\" \"pass1\" {\n  name               = \"pass1\"\n  assume_role_policy = data.aws_iam_policy_document.instance_assume_role_policy.json\n}\n",
  "fix_summary": "Removed the broad AWS-managed AmazonS3ReadOnlyAccess policy from the role. No narrower S3 permissions were added because this file does not identify any required S3 resources."
}
